#!/usr/bin/env python3
"""A standalone, source-preserving Nix binding checker.

The parser records source ranges so that diagnostics and edits use the input's
original spelling and whitespace.  No Nix evaluator or external tool is used.
"""
from __future__ import annotations

import bisect
import difflib
import errno
import json
import os
import re
import stat
import sys
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class Token:
    kind: str
    text: str
    start: int
    end: int


KEYWORDS = {'assert', 'else', 'if', 'in', 'inherit', 'let', 'or', 'rec', 'then', 'with'}
TOKEN_NAMES = {
    '(': 'L_PAREN', ')': 'R_PAREN', '{': 'L_BRACE', '}': 'R_BRACE',
    '[': 'L_BRACK', ']': 'R_BRACK', '=': 'ASSIGN', ';': 'SEMICOLON',
    ':': 'COLON', ',': 'COMMA', '.': 'DOT', '?': 'QUESTION', '@': 'AT',
    '...': 'ELLIPSIS', '+': 'ADD', '-': 'SUB', '*': 'MUL', '/': 'DIV',
    '++': 'CONCAT', '//': 'UPDATE', '==': 'EQUAL', '!=': 'NOT_EQUAL',
    '<': 'LESS', '>': 'MORE', '<=': 'LESS_OR_EQ', '>=': 'MORE_OR_EQ',
    '&&': 'AND', '||': 'OR_OR', '->': 'IMPLICATION', '!': 'INVERT',
    'ID': 'IDENT', 'INT': 'INTEGER', 'FLOAT': 'FLOAT', 'ERROR': 'ERROR',
    'STRING_START': 'STRING_START', 'STRING_END': 'STRING_END',
    'CONTENT': 'STRING_CONTENT', 'INTERPOL_START': 'INTERPOL_START',
    'INTERPOL_END': 'INTERPOL_END', 'PATH_START': 'PATH', 'PATH': 'PATH',
    'URI': 'URI',
}


def token_name(kind):
    return 'TOKEN_' + TOKEN_NAMES.get(kind, kind.upper())


class Source:
    def __init__(self, text):
        self.text = text
        self.bytes = [0]
        for c in text:
            self.bytes.append(self.bytes[-1] + len(c.encode('utf-8')))
        self.lines = [0]
        self.lines.extend(i + 1 for i, c in enumerate(text) if c == '\n')
        self.byte_lines = [self.bytes[i] for i in self.lines]

    def location(self, pos):
        line = bisect.bisect_right(self.lines, pos) - 1
        return line + 1, self.bytes[pos] - self.byte_lines[line] + 1


class Lexer:
    ident = re.compile(r"[A-Za-z_][A-Za-z0-9_'\-]*")
    number = re.compile(r'(?:[0-9]+\.[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|[0-9]+')
    uri = re.compile(r"[A-Za-z][A-Za-z0-9+.-]*:[A-Za-z0-9%/?:@&=+$,_.!~*'\-]+")
    search = re.compile(r'<[A-Za-z0-9._+\-/]+>')
    path_head = re.compile(r'[A-Za-z0-9._+~\-]*/(?![/*\s\[\](){},;]|$)')
    path_char = re.compile(r'[A-Za-z0-9._+~\-/]')

    def __init__(self, source):
        self.source = source
        self.s = source.text
        self.i = 0
        self.tokens = []
        self.comments = []

    def add(self, kind, start, end):
        self.tokens.append(Token(kind, self.s[start:end], start, end))

    def lex(self):
        self.code(False)
        return self.tokens

    def code(self, interpolation):
        s, n = self.s, len(self.s)
        depth = 0
        while self.i < n:
            i = self.i
            c = s[i]
            if c.isspace():
                self.i += 1
                continue
            if c == '#':
                j = s.find('\n', i)
                if j < 0:
                    j = n
                self.comments.append(Token('COMMENT', s[i:j], i, j))
                self.i = j
                continue
            if s.startswith('/*', i):
                j = s.find('*/', i + 2)
                if j < 0:
                    self.add('ERROR', i, n)
                    self.i = n
                else:
                    self.comments.append(Token('COMMENT', s[i:j + 2], i, j + 2))
                    self.i = j + 2
                continue
            if c == '}' and interpolation and depth == 0:
                self.add('INTERPOL_END', i, i + 1)
                self.i += 1
                return
            if c == '"' or s.startswith("''", i):
                self.string(c == '"')
                continue
            if s.startswith('${', i):
                self.add('INTERPOL_START', i, i + 2)
                self.i += 2
                self.code(True)
                continue
            if c == '<':
                m = self.search.match(s, i)
                if m:
                    self.add('PATH', i, m.end())
                    self.i = m.end()
                    continue
            m = self.uri.match(s, i)
            if m:
                self.add('URI', i, m.end())
                self.i = m.end()
                continue
            m = self.path_head.match(s, i)
            # A path may start with an interpolation immediately after its slash.
            is_path = bool(m) or bool(re.match(r'[A-Za-z0-9._+~\-]*/\$\{', s[i:]))
            if is_path and not s.startswith(('//', '/*'), i):
                self.path()
                continue
            m = self.ident.match(s, i)
            if m:
                text = m.group()
                self.add(text if text in KEYWORDS else 'ID', i, m.end())
                self.i = m.end()
                continue
            m = self.number.match(s, i)
            if m:
                text = m.group()
                self.add('FLOAT' if '.' in text else 'INT', i, m.end())
                self.i = m.end()
                continue
            found = False
            for op in ('...', '==', '!=', '<=', '>=', '&&', '||', '->', '//', '++'):
                if s.startswith(op, i):
                    self.add(op, i, i + len(op))
                    self.i += len(op)
                    found = True
                    break
            if found:
                continue
            if c in '(){}[]=;:,.?@+-*/<>!':
                self.add(c, i, i + 1)
                if c == '{':
                    depth += 1
                elif c == '}':
                    depth -= 1
            else:
                self.add('ERROR', i, i + 1)
            self.i += 1

    def string(self, double):
        s, n = self.s, len(self.s)
        i = self.i
        width = 1 if double else 2
        self.add('STRING_START', i, i + width)
        self.i += width
        begin = self.i
        while self.i < n:
            i = self.i
            if double:
                if s[i] == '\\':
                    self.i = min(i + 2, n)
                    continue
                if s[i] == '"':
                    if i > begin:
                        self.add('CONTENT', begin, i)
                    self.add('STRING_END', i, i + 1)
                    self.i = i + 1
                    return
            else:
                if s.startswith("'''", i) or s.startswith("''$", i):
                    self.i += 3
                    continue
                if s.startswith("''\\", i):
                    self.i = min(i + 4, n)
                    continue
                if s.startswith("''", i):
                    if i > begin:
                        self.add('CONTENT', begin, i)
                    self.add('STRING_END', i, i + 2)
                    self.i = i + 2
                    return
            if s.startswith('${', i):
                if i > begin:
                    self.add('CONTENT', begin, i)
                self.add('INTERPOL_START', i, i + 2)
                self.i += 2
                self.code(True)
                begin = self.i
                continue
            self.i += 1
        if n > begin:
            self.add('ERROR', begin, n)

    def path(self):
        s, n = self.s, len(self.s)
        begin = self.i
        self.add('PATH_START', begin, begin)
        while self.i < n:
            i = self.i
            if s.startswith('${', i):
                if i > begin:
                    self.add('CONTENT', begin, i)
                self.add('INTERPOL_START', i, i + 2)
                self.i += 2
                self.code(True)
                begin = self.i
            elif self.path_char.fullmatch(s[i]):
                self.i += 1
            else:
                break
        if self.i > begin:
            self.add('CONTENT', begin, self.i)
        self.add('PATH_END', self.i, self.i)


@dataclass
class Node:
    kind: str
    start: int
    end: int
    children: list = field(default_factory=list)
    token: Optional[Token] = None
    bindings: list = field(default_factory=list)
    body: Optional['Node'] = None
    entries: list = field(default_factory=list)
    alias: Optional[Token] = None
    alias_prefix: bool = False
    open_token: Optional[Token] = None
    close_token: Optional[Token] = None
    at_token: Optional[Token] = None


@dataclass
class Binding:
    kind: str
    start: int
    end: int
    attrs: list
    value: Optional[Node]
    container: Optional[Node] = None


@dataclass
class Entry:
    name: Token
    default: Optional[Node]
    start: int
    end: int
    comma: Optional[Token] = None
    previous_comma: Optional[Token] = None


ATOM_EXPECTED = ['(', 'rec', '{', '[', 'STRING_START', 'ID']
BINARY = {'->': 1, '||': 2, '&&': 3, '==': 4, '!=': 4,
          '<': 5, '>': 5, '<=': 5, '>=': 5, '//': 6, '++': 7,
          '+': 8, '-': 8, '*': 9, '/': 9}


class Parser:
    def __init__(self, source, tokens):
        self.source = source
        self.tokens = tokens
        self.i = 0
        self.errors = []
        self.depth = 0

    def peek(self, offset=0):
        j = self.i + offset
        return self.tokens[j].kind if j < len(self.tokens) else 'EOF'

    def current(self):
        if self.i < len(self.tokens):
            return self.tokens[self.i]
        n = len(self.source.text)
        return Token('EOF', '', n, n)

    def take(self):
        t = self.current()
        if self.i < len(self.tokens):
            self.i += 1
        return t

    def eof_error(self):
        self.errors.append('unexpected end of file')

    def expect(self, kinds):
        if isinstance(kinds, str):
            kinds = [kinds]
        if self.peek() in kinds:
            return self.take()
        suffix = ', wanted any of [' + ', '.join(token_name(k) for k in kinds) + ']'
        first = self.current()
        end = first.end
        if first.kind != 'EOF':
            while self.peek() not in kinds and self.peek() != 'EOF':
                end = self.take().end
            self.errors.append('unexpected ' + token_name(first.kind) + ' at ' +
                               str(self.source.bytes[first.start]) + '..' + str(self.source.bytes[end]) + suffix)
        if self.peek() == 'EOF':
            self.errors.append('unexpected end of file' + suffix)
            return self.current()
        return self.take()

    def close(self, kind):
        if self.peek() == 'EOF':
            self.eof_error()
            return self.current()
        return self.expect(kind)

    def parse(self):
        result = self.expr()
        if self.peek() != 'EOF':
            start = self.current().start
            end = self.tokens[-1].end
            self.errors.append(f'unexpected token at {self.source.bytes[start]}..{self.source.bytes[end]}')
        return result

    def expr(self, min_bp=0):
        self.depth += 1
        if self.depth > 300:
            self.errors.append('recursion limit exceeded')
            self.i = len(self.tokens)
            self.depth -= 1
            t = self.current()
            return Node('atom', t.start, t.end)
        left = self.primary()
        while self.peek() != 'EOF':
            k = self.peek()
            if k == '.' and 14 >= min_bp:
                self.take()
                attrs = self.attrpath()
                children = [left] + [a for a in attrs if a.kind != 'attr']
                end = attrs[-1].end if attrs else left.end
                if self.peek() == 'or':
                    self.take()
                    default = self.expr(0)
                    children.append(default)
                    end = default.end
                left = Node('compound', left.start, end, children)
            elif k == '?' and 11 >= min_bp:
                self.take()
                attrs = self.attrpath()
                left = Node('compound', left.start, attrs[-1].end if attrs else left.end,
                            [left] + [a for a in attrs if a.kind != 'attr'])
            elif k in BINARY and BINARY[k] >= min_bp:
                self.take()
                bp = BINARY[k]
                right = self.expr(bp if k in ('->', '//', '++') else bp + 1)
                left = Node('compound', left.start, right.end, [left, right])
            elif k in ('ID', 'INT', 'FLOAT', 'STRING_START', 'PATH_START', 'PATH', 'URI', '(', '[', '{', 'rec') and 12 >= min_bp:
                right = self.expr(13)
                left = Node('compound', left.start, right.end, [left, right])
            else:
                break
        self.depth -= 1
        return left

    def primary(self):
        t = self.current()
        k = t.kind
        if k == 'EOF':
            self.eof_error()
            return Node('atom', t.start, t.end)
        if k == 'ID':
            self.take()
            if self.peek() == ':':
                self.take()
                body = self.expr()
                return Node('lambda', t.start, body.end, body=body, token=t)
            if self.peek() == '@':
                at = self.take()
                op = self.expect('{')
                return self.pattern(op, alias=t, at=at)
            return Node('ref', t.start, t.end, token=t)
        if k in ('INT', 'FLOAT', 'URI', 'PATH'):
            self.take()
            return Node('atom', t.start, t.end)
        if k in ('STRING_START', 'PATH_START'):
            return self.string()
        if k == 'let':
            self.take()
            if self.peek() == '{':
                op = self.take()
                return self.binding_set('legacy', t, op, '}')
            return self.binding_set('let', t, None, 'in')
        if k == 'rec':
            self.take()
            op = self.expect('{')
            return self.binding_set('rec', t, op, '}')
        if k == '{':
            self.take()
            pattern = self.peek() == '...' or (self.peek() in ('ID', 'or') and self.peek(1) in (',', '?', '}'))
            if self.peek() == '}' and self.peek(1) in (':', '@'):
                pattern = True
            if pattern:
                return self.pattern(t)
            return self.binding_set('set', t, t, '}')
        if k == '(':
            self.take()
            sub = self.expr()
            close = self.close(')')
            return Node('compound', t.start, close.end, [sub])
        if k == '[':
            self.take()
            children = []
            while self.peek() not in (']', 'EOF'):
                old = self.i
                children.append(self.expr(13))
                if self.i == old:
                    self.take()
            close = self.close(']')
            return Node('compound', t.start, close.end, children)
        if k in ('with', 'assert'):
            self.take()
            a = self.expr()
            self.expect(';')
            b = self.expr()
            return Node('compound', t.start, b.end, [a, b])
        if k == 'if':
            self.take()
            a = self.expr()
            self.expect('then')
            b = self.expr()
            self.expect('else')
            c = self.expr()
            return Node('compound', t.start, c.end, [a, b, c])
        if k in ('-', '!'):
            self.take()
            sub = self.expr(10)
            return Node('compound', t.start, sub.end, [sub])
        self.take()
        suffix = ', wanted any of [' + ', '.join(token_name(x) for x in ATOM_EXPECTED) + ']'
        self.errors.append(f'unexpected {token_name(k)} at {self.source.bytes[t.start]}..{self.source.bytes[t.end]}' + suffix)
        return Node('atom', t.start, t.end)

    def string(self):
        t = self.take()
        end_kind = 'STRING_END' if t.kind == 'STRING_START' else 'PATH_END'
        children = []
        end = t.end
        while self.peek() not in (end_kind, 'EOF'):
            if self.peek() == 'CONTENT':
                end = self.take().end
            elif self.peek() == 'INTERPOL_START':
                self.take()
                children.append(self.expr())
                end = self.close('INTERPOL_END').end
            else:
                self.expect([end_kind, 'CONTENT', 'INTERPOL_START'])
        if self.peek() == 'EOF' and end_kind == 'STRING_END':
            # The string loop requests one more part before requesting its end.
            if not self.errors or not self.errors[-1].endswith('[TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]'):
                self.expect(['STRING_END', 'CONTENT', 'INTERPOL_START'])
        end = self.expect(end_kind).end
        return Node('compound', t.start, end, children)

    def attr(self):
        t = self.current()
        if t.kind == 'STRING_START':
            return self.string()
        if t.kind == 'INTERPOL_START':
            self.take()
            val = self.expr()
            end = self.close('INTERPOL_END')
            return Node('compound', t.start, end.end, [val])
        tok = self.expect(['ID', 'or'])
        return Node('attr', tok.start, tok.end, token=tok)

    def attrpath(self):
        attrs = [self.attr()]
        while self.peek() == '.':
            self.take()
            attrs.append(self.attr())
        return attrs

    def binding_set(self, kind, first, op, closing):
        node = Node(kind, first.start, first.end, open_token=op)
        while self.peek() not in (closing, 'EOF'):
            old = self.i
            t = self.current()
            if self.peek() == 'inherit':
                self.take()
                value = None
                if self.peek() == '(':
                    self.take()
                    value = self.expr()
                    self.close(')')
                attrs = []
                while self.peek() not in (';', 'EOF'):
                    j = self.i
                    attrs.append(self.attr())
                    if j == self.i:
                        break
                end = self.expect(';')
                binding = Binding('inherit', t.start, end.end, attrs, value, node)
            else:
                attrs = self.attrpath()
                self.expect('=')
                value = self.expr()
                end = self.expect(';')
                binding = Binding('value', t.start, end.end, attrs, value, node)
            node.bindings.append(binding)
            if old == self.i:
                self.take()
        close = self.close(closing)
        node.close_token = close
        node.end = close.end
        if kind == 'let':
            node.body = self.expr()
            node.end = node.body.end
        return node

    def pattern(self, op, alias=None, at=None):
        node = Node('pattern', alias.start if alias else op.start, op.end,
                    alias=alias, alias_prefix=alias is not None, open_token=op, at_token=at)
        previous = None
        while self.peek() not in ('}', 'EOF'):
            old = self.i
            if self.peek() == '...':
                self.take()
                break
            name = self.expect('ID')
            default = None
            end = name.end
            if self.peek() == '?':
                self.take()
                default = self.expr()
                end = default.end
            entry = Entry(name, default, name.start, end, previous_comma=previous)
            node.entries.append(entry)
            if self.peek() != ',':
                break
            previous = self.take()
            entry.comma = previous
            if old == self.i:
                break
        node.close_token = self.expect('}')
        if self.peek() == '@':
            node.at_token = self.take()
            node.alias = self.expect('ID')
            node.alias_prefix = False
        self.expect(':')
        node.body = self.expr()
        node.end = node.body.end
        return node


@dataclass
class Options:
    no_lambda: bool = False
    no_pattern: bool = False
    no_underscore: bool = False
    warn_underscore: bool = False
    quiet: bool = False
    edit: bool = False
    hidden: bool = False
    fail: bool = False
    output: str = 'human-readable'
    excludes: list = field(default_factory=list)
    paths: list = field(default_factory=list)


@dataclass(eq=False)
class Declaration:
    token: Token
    category: str
    owner: Node
    binding: Optional[Binding] = None
    entry: Optional[Entry] = None
    alias: bool = False
    deps: set = field(default_factory=set)
    protected: bool = False
    used: bool = False

    @property
    def name(self):
        return self.token.text

    @property
    def message(self):
        return ('Used ' if self.used else 'Unused ') + self.category + ': ' + self.name


class Analyzer:
    def __init__(self, source, comments, options):
        self.source = source
        self.options = options
        self.comments = comments
        self.issues = []
        self.scopes = []
        self.skip_ranges = []
        for comment in comments:
            if 'deadnix: skip' in comment.text:
                end_line = source.location(comment.end)[0]
                # A pragma covers following text through the end of the next line.
                stop = source.lines[end_line + 1] if end_line + 1 < len(source.lines) else len(source.text) + 1
                self.skip_ranges.append((comment.end, stop))

    def protected(self, d):
        o = self.options
        if any(a <= d.token.start < b for a, b in self.skip_ranges):
            return True
        if d.category == 'lambda argument':
            return o.no_lambda or d.name.startswith('_')
        if d.category == 'lambda pattern' and not d.alias and o.no_pattern:
            return True
        return o.no_underscore and d.name.startswith('_')

    def solve(self, declarations, roots):
        active = set(declarations)
        for d in declarations:
            d.protected = self.protected(d)
        while True:
            used = set(roots)
            for d in active:
                used.update(d.deps - {d.name})
            remove = {d for d in active if not d.protected and
                      (d.name not in used or (self.options.warn_underscore and d.name.startswith('_')))}
            if not remove:
                break
            active -= remove
        for d in declarations:
            if not d.protected and (d.name not in used or
                                    (self.options.warn_underscore and d.name.startswith('_'))):
                d.used = d.name in used
                self.issues.append(d)
        self.scopes.append((declarations, roots))

    def visit(self, node):
        if node is None:
            return set()
        if node.kind == 'ref':
            return {node.token.text}
        if node.kind in ('atom', 'attr'):
            return set()
        if node.kind == 'lambda':
            refs = self.visit(node.body)
            d = Declaration(node.token, 'lambda argument', node)
            self.solve([d], refs)
            return refs - {d.name}
        if node.kind == 'pattern':
            roots = self.visit(node.body)
            decls, all_refs = [], set(roots)
            counts = {}
            for e in node.entries:
                refs = self.visit(e.default)
                all_refs.update(refs)
                d = Declaration(e.name, 'lambda pattern', node, entry=e, deps=refs)
                decls.append(d)
                counts[d.name] = counts.get(d.name, 0) + 1
            for name, count in counts.items():
                if count > 1:
                    roots.add(name)
            if node.alias:
                decls.append(Declaration(node.alias, 'lambda pattern', node, alias=True))
            self.solve(decls, roots)
            return all_refs - {d.name for d in decls}
        if node.kind in ('let', 'rec', 'set', 'legacy'):
            decls = []
            roots = self.visit(node.body)
            all_refs = set(roots)
            inherit_outer = set()
            names = set()
            for b in node.bindings:
                refs = self.visit(b.value)
                if b.kind == 'value':
                    for a in b.attrs:
                        if a.kind != 'attr':
                            refs.update(self.visit(a))
                    if b.attrs and b.attrs[0].kind == 'attr':
                        tok = b.attrs[0].token
                        names.add(tok.text)
                        if node.kind == 'let':
                            decls.append(Declaration(tok, 'let binding', node, binding=b, deps=refs))
                        else:
                            roots.update(refs)
                    else:
                        roots.update(refs)
                    all_refs.update(refs)
                else:
                    identifiers = [a.token for a in b.attrs if a.kind == 'attr']
                    if b.value is None:
                        inherit_outer.update(t.text for t in identifiers)
                    # The expression of inherit is an outer expression; its own
                    # declared names do not turn it into a recursive definition.
                    for tok in identifiers:
                        names.add(tok.text)
                        if node.kind == 'let':
                            decls.append(Declaration(tok, 'let binding', node, binding=b, deps=set(refs)))
                    if not identifiers or node.kind != 'let':
                        roots.update(refs)
                    all_refs.update(refs)
                    if b.value is not None:
                        inherit_outer.update(refs.intersection(t.text for t in identifiers))
            if node.kind == 'let':
                self.solve(decls, roots)
            if node.kind == 'set':
                return all_refs | inherit_outer
            return (all_refs - names) | inherit_outer
        refs = set()
        for c in node.children:
            refs.update(self.visit(c))
        return refs

    def analyze(self, tree):
        self.visit(tree)
        self.issues.sort(key=lambda d: d.token.start)
        return self.issues


def preceding_space(text, index):
    while index > 0 and text[index - 1].isspace():
        index -= 1
    return index


class EditOverlap(Exception):
    def __init__(self, begin, end):
        self.begin = begin
        self.end = end


def edit_source(source, issues):
    text = source.text
    changes = []
    groups = {}
    scopes = {}
    for d in issues:
        if d.category == 'let binding':
            groups.setdefault(id(d.binding), (d.binding, []) )[1].append(d)
            scopes[id(d.owner)] = d.owner
        elif d.category == 'lambda argument':
            changes.append((d.token.start, d.token.start, '_'))
        elif d.alias:
            node = d.owner
            if node.alias_prefix:
                changes.append((d.token.start, node.open_token.start, ''))
            else:
                changes.append((preceding_space(text, node.at_token.start), d.token.end, ''))
        else:
            e = d.entry
            if e.comma:
                start = preceding_space(text, e.start)
                end = e.comma.end
            elif e.previous_comma:
                start = e.previous_comma.start
                end = e.end
            else:
                start = preceding_space(text, e.start)
                end = e.end
            changes.append((start, end, ''))
    removed = set()
    binding_changes = {}
    for key, (b, ds) in groups.items():
        if b.kind == 'value' or len(ds) == len(b.attrs):
            removed.add(key)
            binding_changes[key] = [(preceding_space(text, b.start), b.end, '')]
        else:
            binding_changes[key] = [(preceding_space(text, d.token.start), d.token.end, '') for d in ds]
    empty_scopes = set()
    for scope in scopes.values():
        if all(id(b) in removed for b in scope.bindings):
            empty_scopes.add(id(scope))
            changes.append((scope.start, scope.body.start, ''))
    for b, ds in groups.values():
        if id(b.container) not in empty_scopes:
            changes.extend(binding_changes[id(b)])
    # An edit deleting a whole expression subsumes edits within that expression.
    changes.sort(key=lambda c: (c[0], -c[1]))
    filtered = []
    for c in changes:
        if filtered and c[0] >= filtered[-1][0] and c[1] <= filtered[-1][1] and filtered[-1][1] > filtered[-1][0]:
            continue
        filtered.append(c)
    result = []
    pos = 0
    for start, end, replacement in filtered:
        if pos > start:
            raise EditOverlap(source.bytes[pos], source.bytes[start])
        result.append(text[pos:start])
        result.append(replacement)
        pos = end
    result.append(text[pos:])
    return ''.join(result)


def diagnostic_json(source, issues):
    result = []
    for d in issues:
        line, column = source.location(d.token.start)
        end_column = column + source.bytes[d.token.end] - source.bytes[d.token.start]
        result.append({'column': column, 'endColumn': end_column, 'line': line, 'message': d.message})
    return result


def render_human(path, source, issues, colors):
    def color(text, code):
        return '\x1b[' + code + 'm' + text + '\x1b[0m' if colors else text

    def shade(d):
        return {'let binding': '31', 'lambda argument': '36', 'lambda pattern': '35'}[d.category]

    groups = {}
    for d in issues:
        line, col = source.location(d.token.start)
        groups.setdefault(line, []).append(d)
    width = len(str(max(groups)))
    first_line, first_column = source.location(issues[0].token.start)
    out = [color('Warning:', '33') + ' Unused declarations were found.\n',
           ' ' * (width + 2) + color('╭', '38;5;246') + color('─', '38;5;246') + color('[', '38;5;246') +
           path + f':{first_line}:{first_column}' + color(']', '38;5;246') + '\n']
    for line, ds in groups.items():
        begin = source.lines[line - 1]
        end = source.lines[line] if line < len(source.lines) else len(source.text)
        raw = source.text[begin:end].rstrip('\r\n')
        displayed = []
        positions = []
        for index, c in enumerate(raw):
            positions.append(len(displayed))
            code = '38;5;249'
            for d in ds:
                if d.token.start <= begin + index < d.token.end:
                    code = shade(d)
                    break
            if c == '\t':
                for _ in range(4 - len(displayed) % 4):
                    displayed.append((' ', code))
            else:
                displayed.append((c, code))
        positions.append(len(displayed))
        out.append(' ' + color(f'{line:>{width}} │', '38;5;246') + ''.join(color(c, code) for c, code in displayed) + '\n')
        labels = []
        for d in ds:
            a = min(d.token.start - begin, len(raw))
            b = min(d.token.end - begin, len(raw))
            middle = (a + b) // 2
            labels.append((positions[middle], positions[b], d))
        right = max(e for m, e, d in labels)
        for j in range(len(labels) - 1, -1, -1):
            mid, end, d = labels[j]
            row = []
            earlier = {m: dd for m, e, dd in labels[:j]}
            for x in range(right + 1):
                if x == mid:
                    row.append(color('╰', shade(d)))
                elif x > mid:
                    row.append(color('─', shade(d)))
                elif x in earlier:
                    row.append(color('│', shade(earlier[x])))
                else:
                    row.append(' ')
            out.append(' ' + color(' ' * (width + 1) + '│', '38;5;240') + ''.join(row) + ' ' + d.message + '\n')
    return ''.join(out)


HELP_OPTIONS = """Options:
  -l, --no-lambda-arg                  Don't check lambda parameter arguments
  -L, --no-lambda-pattern-names        Don't check lambda attrset pattern names (don't break nixpkgs callPackage)
  -_, --no-underscore                  Don't check any bindings that start with a _
                                       (Lambda arguments starting with _ are not checked anyway.)
  -W, --warn-used-underscore           Warn if bindings are referenced that start with '_'
  -q, --quiet                          Don't print dead code report
  -e, --edit                           Remove unused code and write to source file
  -h, --hidden                         Recurse into hidden subdirectories and process hidden .*.nix files
      --help                           
  -f, --fail                           Exit with 1 if unused code has been found
  -o, --output-format <OUTPUT_FORMAT>  Output format to use [default: human-readable] [possible values: human-readable, json]
      --exclude <EXCLUDES>...          Files to exclude from analysis
  -V, --version                        Print version
"""
FLAGS = {
    'l': ('no_lambda', 'no-lambda-arg'),
    'L': ('no_pattern', 'no-lambda-pattern-names'),
    '_': ('no_underscore', 'no-underscore'),
    'W': ('warn_underscore', 'warn-used-underscore'),
    'q': ('quiet', 'quiet'),
    'e': ('edit', 'edit'),
    'h': ('hidden', 'hidden'),
    'f': ('fail', 'fail'),
}


class CLIError(Exception):
    def __init__(self, text):
        self.text = text


def parse_options(argv, prog):
    opt = Options()
    usage = f'Usage: {prog} [OPTIONS] [FILE_PATHS]...'
    footer = "For more information, try '--help'.\n"
    seen = set()
    long_flags = {b: (a, b) for a, b in FLAGS.values()}
    i = 0
    positional = False

    def duplicate(name, display=None):
        if name in seen:
            raise CLIError(f"error: the argument '{display or '--' + name}' cannot be used multiple times\n\n{usage}\n\n{footer}")
        seen.add(name)

    def flag(name):
        attr, full = long_flags[name]
        duplicate(full)
        setattr(opt, attr, True)

    def unknown(arg):
        tip = f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
        raise CLIError(f"error: unexpected argument '{arg}' found\n\n{tip}{usage}\n\n{footer}")

    def value_error(name):
        label = '--output-format <OUTPUT_FORMAT>' if name == 'output-format' else '--exclude <EXCLUDES>...'
        more = '\n  [possible values: human-readable, json]' if name == 'output-format' else ''
        raise CLIError(f"error: a value is required for '{label}' but none was supplied{more}\n\n{footer}")

    def output(value):
        if value not in ('human-readable', 'json'):
            raise CLIError(f"error: invalid value '{value}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\n{footer}")
        opt.output = value

    while i < len(argv):
        arg = argv[i]
        i += 1
        if positional or arg == '-' or not arg.startswith('-'):
            opt.paths.append(arg)
            continue
        if arg == '--':
            positional = True
            continue
        if arg.startswith('--'):
            parts = arg[2:].split('=', 1)
            name = parts[0]
            val = parts[1] if len(parts) > 1 else None
            if name == 'help' and val is None:
                print('Find dead code in .nix files\n\n' + usage + '\n\nArguments:\n  [FILE_PATHS]...  .nix files, or directories with .nix files inside [default: .]\n\n' + HELP_OPTIONS, end='')
                raise SystemExit(0)
            if name == 'version' and val is None:
                print('deadnix 1.3.1')
                raise SystemExit(0)
            if name in long_flags:
                if val is not None:
                    raise CLIError(f"error: unexpected value '{val}' for '--{name}' found; no more were expected\n\n{usage}\n\n{footer}")
                flag(name)
            elif name == 'output-format':
                duplicate(name, '--output-format <OUTPUT_FORMAT>')
                if val is None:
                    if i >= len(argv) or (argv[i].startswith('-') and argv[i] != '-'):
                        value_error(name)
                    val = argv[i]
                    i += 1
                output(val)
            elif name == 'exclude':
                duplicate(name, '--exclude <EXCLUDES>...')
                vals = [] if val is None else [val]
                while i < len(argv) and (not argv[i].startswith('-') or argv[i] == '-'):
                    vals.append(argv[i])
                    i += 1
                if not vals:
                    value_error(name)
                opt.excludes.extend(vals)
            else:
                unknown(arg if val is None else '--' + name)
        else:
            j = 1
            while j < len(arg):
                ch = arg[j]
                j += 1
                if ch in FLAGS:
                    flag(FLAGS[ch][1])
                elif ch == 'V':
                    print('deadnix 1.3.1')
                    raise SystemExit(0)
                elif ch == 'o':
                    duplicate('output-format', '--output-format <OUTPUT_FORMAT>')
                    if j < len(arg):
                        val = arg[j:]
                        if val.startswith('='):
                            val = val[1:]
                        j = len(arg)
                    else:
                        if i >= len(argv) or (argv[i].startswith('-') and argv[i] != '-'):
                            value_error('output-format')
                        val = argv[i]
                        i += 1
                    output(val)
                else:
                    unknown('-' + ch)
    if not opt.paths:
        opt.paths = ['.']
    return opt


def os_error(exc):
    if isinstance(exc, UnicodeError):
        return 'stream did not contain valid UTF-8'
    return f'{exc.strerror} (os error {exc.errno})'


def json_report(path, results):
    print(json.dumps({'file': path, 'results': results}, ensure_ascii=False, separators=(',', ':')))


class Application:
    def __init__(self, options):
        self.options = options
        self.found = False
        self.colors = 'NO_COLOR' not in os.environ
        self.exclude = [os.path.abspath(p) for p in options.excludes]

    def error(self, path, message, stage):
        if self.options.output == 'json':
            json_report(path, [{'message': message}])
        else:
            print(f'Error {stage} file {path}: {message}', file=sys.stderr)

    def process_file(self, path):
        try:
            with open(path, 'r', encoding='utf-8', newline='') as f:
                text = f.read()
        except (OSError, UnicodeError) as e:
            self.error(path, os_error(e), 'reading')
            return
        source = Source(text)
        lexer = Lexer(source)
        parser = Parser(source, lexer.lex())
        try:
            tree = parser.parse()
        except RecursionError:
            parser.errors.append('recursion limit exceeded')
            tree = None
        if parser.errors:
            if self.options.output == 'json':
                json_report(path, [{'message': msg} for msg in parser.errors])
            else:
                for message in parser.errors:
                    self.error(path, message, 'parsing')
            return
        try:
            issues = Analyzer(source, lexer.comments, self.options).analyze(tree)
        except RecursionError:
            self.error(path, 'recursion limit exceeded', 'parsing')
            return
        if not issues:
            return
        self.found = True
        if not self.options.quiet:
            if self.options.output == 'json':
                json_report(path, diagnostic_json(source, issues))
            else:
                print(render_human(path, source, issues, self.colors), end='')
        if self.options.edit:
            try:
                edited = edit_source(source, issues)
            except EditOverlap as e:
                sys.stdout.flush()
                print(f"\nthread 'main' ({os.getpid()}) panicked at src/edit.rs:20:33:\nbegin <= end ({e.begin} <= {e.end}) when slicing `{text}`\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", file=sys.stderr)
                raise SystemExit(101)
            try:
                with open(path, 'w', encoding='utf-8', newline='') as f:
                    f.write(edited)
            except OSError as e:
                self.error(path, os_error(e), 'writing')

    def walk(self, path):
        absolute = os.path.abspath(path)
        if any(absolute == x or absolute.startswith(x + os.sep) for x in self.exclude):
            return
        try:
            entries = list(os.scandir(path))
        except OSError as e:
            self.error(path, os_error(e), 'reading directory')
            return
        for entry in entries:
            if not self.options.hidden and entry.name.startswith('.'):
                continue
            child = os.path.join(path, entry.name)
            abs_child = os.path.abspath(child)
            if any(abs_child == x or abs_child.startswith(x + os.sep) for x in self.exclude):
                continue
            try:
                if entry.is_dir(follow_symlinks=False):
                    self.walk(child)
                elif entry.is_file(follow_symlinks=False) and os.path.splitext(entry.name)[1].lower() == '.nix':
                    self.process_file(child)
            except OSError as e:
                self.error(child, os_error(e), 'stating')

    def run(self):
        for path in self.options.paths:
            try:
                metadata = os.stat(path)
            except OSError as e:
                self.error(path, os_error(e), 'stating')
                continue
            if stat.S_ISDIR(metadata.st_mode):
                self.walk(path)
            else:
                self.process_file(path)
        return 1 if self.found and self.options.fail else 0


def main():
    sys.setrecursionlimit(5000)
    prog = os.path.basename(sys.argv[0])
    try:
        options = parse_options(sys.argv[1:], prog)
    except CLIError as e:
        sys.stderr.write(e.text)
        return 2
    return Application(options).run()


if __name__ == '__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except BrokenPipeError:
            pass
        sys.exit(0)
