FLAGS = {
    'l': ('no_lambda', 'no-lambda-arg'),
    'L': ('no_pattern', 'no-lambda-pattern-names'),
    '_': ('no_underscore', 'no-underscore'),
    'W': ('warn_underscore', 'warn-used-underscore'),
    'q': ('quiet', 'quiet'),
    'e': ('edit', 'edit'),
    'h': ('hidden', 'hidden'),
    'f': ('fail', 'fail'),
}


class CLIError(Exception):
    def __init__(self, text):
        self.text = text


def parse_options(argv, prog):
    opt = Options()
    usage = f'Usage: {prog} [OPTIONS] [FILE_PATHS]...'
    footer = "For more information, try '--help'.\n"
    seen = set()
    long_flags = {b: (a, b) for a, b in FLAGS.values()}
    i = 0
    positional = False

    def duplicate(name, display=None):
        if name in seen:
            raise CLIError(f"error: the argument '{display or '--' + name}' cannot be used multiple times\n\n{usage}\n\n{footer}")
        seen.add(name)

    def flag(name):
        attr, full = long_flags[name]
        duplicate(full)
        setattr(opt, attr, True)

    def unknown(arg):
        tip = f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
        raise CLIError(f"error: unexpected argument '{arg}' found\n\n{tip}{usage}\n\n{footer}")

    def value_error(name):
        label = '--output-format <OUTPUT_FORMAT>' if name == 'output-format' else '--exclude <EXCLUDES>...'
        more = '\n  [possible values: human-readable, json]' if name == 'output-format' else ''
        raise CLIError(f"error: a value is required for '{label}' but none was supplied{more}\n\n{footer}")

    def output(value):
        if value not in ('human-readable', 'json'):
            raise CLIError(f"error: invalid value '{value}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\n{footer}")
        opt.output = value

    while i < len(argv):
        arg = argv[i]
        i += 1
        if positional or arg == '-' or not arg.startswith('-'):
            opt.paths.append(arg)
            continue
        if arg == '--':
            positional = True
            continue
        if arg.startswith('--'):
            parts = arg[2:].split('=', 1)
            name = parts[0]
            val = parts[1] if len(parts) > 1 else None
            if name == 'help' and val is None:
                print('Find dead code in .nix files\n\n' + usage + '\n\nArguments:\n  [FILE_PATHS]...  .nix files, or directories with .nix files inside [default: .]\n\n' + HELP_OPTIONS, end='')
                raise SystemExit(0)
            if name == 'version' and val is None:
                print('deadnix 1.3.1')
                raise SystemExit(0)
            if name in long_flags:
                if val is not None:
                    raise CLIError(f"error: unexpected value '{val}' for '--{name}' found; no more were expected\n\n{usage}\n\n{footer}")
                flag(name)
            elif name == 'output-format':
                duplicate(name, '--output-format <OUTPUT_FORMAT>')
                if val is None:
                    if i >= len(argv) or (argv[i].startswith('-') and argv[i] != '-'):
                        value_error(name)
                    val = argv[i]
                    i += 1
                output(val)
            elif name == 'exclude':
                duplicate(name, '--exclude <EXCLUDES>...')
                vals = [] if val is None else [val]
                while i < len(argv) and (not argv[i].startswith('-') or argv[i] == '-'):
                    vals.append(argv[i])
                    i += 1
                if not vals:
                    value_error(name)
                opt.excludes.extend(vals)
            else:
                unknown(arg if val is None else '--' + name)
        else:
            j = 1
            while j < len(arg):
                ch = arg[j]
                j += 1
                if ch in FLAGS:
                    flag(FLAGS[ch][1])
                elif ch == 'V':
                    print('deadnix 1.3.1')
                    raise SystemExit(0)
                elif ch == 'o':
                    duplicate('output-format', '--output-format <OUTPUT_FORMAT>')
                    if j < len(arg):
                        val = arg[j:]
                        if val.startswith('='):
                            val = val[1:]
                        j = len(arg)
                    else:
                        if i >= len(argv) or (argv[i].startswith('-') and argv[i] != '-'):
                            value_error('output-format')
                        val = argv[i]
                        i += 1
                    output(val)
                else:
                    unknown('-' + ch)
    if not opt.paths:
        opt.paths = ['.']
    return opt


def os_error(exc):
    if isinstance(exc, UnicodeError):
        return 'stream did not contain valid UTF-8'
    return f'{exc.strerror} (os error {exc.errno})'


def json_report(path, results):
    print(json.dumps({'file': path, 'results': results}, ensure_ascii=False, separators=(',', ':')))


class Application:
    def __init__(self, options):
        self.options = options
        self.found = False
        self.colors = 'NO_COLOR' not in os.environ
        self.exclude = [os.path.abspath(p) for p in options.excludes]

    def error(self, path, message, stage):
        if self.options.output == 'json':
            json_report(path, [{'message': message}])
        else:
            print(f'Error {stage} file {path}: {message}', file=sys.stderr)

    def process_file(self, path):
        try:
            with open(path, 'r', encoding='utf-8', newline='') as f:
                text = f.read()
        except (OSError, UnicodeError) as e:
            self.error(path, os_error(e), 'reading')
            return
        source = Source(text)
        lexer = Lexer(source)
        parser = Parser(source, lexer.lex())
        try:
            tree = parser.parse()
        except RecursionError:
            parser.errors.append('recursion limit exceeded')
            tree = None
        if parser.errors:
            if self.options.output == 'json':
                json_report(path, [{'message': msg} for msg in parser.errors])
            else:
                for message in parser.errors:
                    self.error(path, message, 'parsing')
            return
        try:
            issues = Analyzer(source, lexer.comments, self.options).analyze(tree)
        except RecursionError:
            self.error(path, 'recursion limit exceeded', 'parsing')
            return
        if not issues:
            return
        self.found = True
        if not self.options.quiet:
            if self.options.output == 'json':
                json_report(path, diagnostic_json(source, issues))
            else:
                print(render_human(path, source, issues, self.colors), end='')
        if self.options.edit:
            try:
                edited = edit_source(source, issues)
            except EditOverlap as e:
                sys.stdout.flush()
                print(f"\nthread 'main' ({os.getpid()}) panicked at src/edit.rs:20:33:\nbegin <= end ({e.begin} <= {e.end}) when slicing `{text}`\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", file=sys.stderr)
                raise SystemExit(101)
            try:
                with open(path, 'w', encoding='utf-8', newline='') as f:
                    f.write(edited)
            except OSError as e:
                self.error(path, os_error(e), 'writing')

    def walk(self, path):
        absolute = os.path.abspath(path)
        if any(absolute == x or absolute.startswith(x + os.sep) for x in self.exclude):
            return
        try:
            entries = list(os.scandir(path))
        except OSError as e:
            self.error(path, os_error(e), 'reading directory')
            return
        for entry in entries:
            if not self.options.hidden and entry.name.startswith('.'):
                continue
            child = os.path.join(path, entry.name)
            abs_child = os.path.abspath(child)
            if any(abs_child == x or abs_child.startswith(x + os.sep) for x in self.exclude):
                continue
            try:
                if entry.is_dir(follow_symlinks=False):
                    self.walk(child)
                elif entry.is_file(follow_symlinks=False) and os.path.splitext(entry.name)[1].lower() == '.nix':
                    self.process_file(child)
            except OSError as e:
                self.error(child, os_error(e), 'stating')

    def run(self):
        for path in self.options.paths:
            try:
                metadata = os.stat(path)
            except OSError as e:
                self.error(path, os_error(e), 'stating')
                continue
            if stat.S_ISDIR(metadata.st_mode):
                self.walk(path)
            else:
                self.process_file(path)
        return 1 if self.found and self.options.fail else 0


def main():
    sys.setrecursionlimit(5000)
    prog = os.path.basename(sys.argv[0])
    try:
        options = parse_options(sys.argv[1:], prog)
    except CLIError as e:
        sys.stderr.write(e.text)
        return 2
    return Application(options).run()


if __name__ == '__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except BrokenPipeError:
            pass
        sys.exit(0)
